<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_login();$pdo=staff_db();$status=$_GET['status']??'';$q=trim($_GET['q']??'');$sql="SELECT p.*,c.name customer_name,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) manager_name,(SELECT COUNT(*) FROM tasks t WHERE t.project_id=p.id AND t.status NOT IN('completed','cancelled')) open_tasks FROM projects p JOIN customers c ON c.id=p.customer_id LEFT JOIN staff s ON s.id=p.assigned_manager WHERE 1";$args=[];if($status!==''){$sql.=' AND p.status=?';$args[]=$status;}if($q!==''){$like='%'.$q.'%';$sql.=' AND (p.project_code LIKE ? OR p.name LIKE ? OR c.name LIKE ?)';array_push($args,$like,$like,$like);}$sql.=' ORDER BY p.updated_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$pageTitle='Projects';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Operations</p><h1>Projects</h1><p class="muted">Track each accepted job from consultation to completion.</p></div><a class="btn" href="<?= h(ideare_root_url('staff/pages/customers.php')) ?>">Create from customer</a></div><section class="staff-panel"><form class="search-row" method="get"><label>Search<input name="q" value="<?= h($q) ?>" placeholder="Project code, name or customer"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(project_statuses() as $k=>$v):?><option value="<?= $k ?>" <?= $status===$k?'selected':'' ?>><?= h($v) ?></option><?php endforeach;?></select></label><button class="btn">Filter</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Project</th><th>Customer</th><th>Status</th><th>Manager</th><th>Open tasks</th><th>Target</th><th>Value</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="<?= h(ideare_root_url('staff/pages/project-view.php?id='.$r['id'])) ?>"><b><?= h($r['name']) ?></b></a><small><?= h($r['project_code']) ?></small></td><td><?= h($r['customer_name']) ?></td><td><span class="pill <?= h($r['status']) ?>"><?= h(str_replace('_',' ',$r['status'])) ?></span></td><td><?= h($r['manager_name']?:'Unassigned') ?></td><td><?= (int)$r['open_tasks'] ?></td><td><?= $r['target_date']?h(date('j M Y',strtotime($r['target_date']))):'—' ?></td><td><?= money($r['estimated_value']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty-state">No projects found.</td></tr><?php endif;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php'; ?>
